import{_ as t,a0 as d,w as r,s as o,I as n,x as a,a1 as p,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"備忘單：提升你的 MariaDB 和 MySQL 資料庫技能 | LCTT x X-CMD","titleTemplate":false,"description":"備忘單：提升你的 MariaDB 和 MySQL 資料庫技能 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"備忘單：提升你的 MariaDB 和 MySQL 資料庫技能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"備忘單：提升你的 MariaDB 和 MySQL 資料庫技能 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201029 Improve your database knowledge with this MariaDB and MySQL cheat sheet","title":"備忘單：提升你的 MariaDB 和 MySQL 資料庫技能","tag":"202011","desc":""},"relativePath":"202011/20201029 Improve your database knowledge with this MariaDB and MySQL cheat sheet.md","filePath":"[post].md"}'),c={name:"202011/20201029 Improve your database knowledge with this MariaDB and MySQL cheat sheet.md"};function h(g,s,b,u,k,m){const e=d("Link");return r(),o("div",null,[s[40]||(s[40]=n("h1",{id:"備忘單-提升你的-mariadb-和-mysql-資料庫技能",tabindex:"-1"},[a("備忘單：提升你的 MariaDB 和 MySQL 資料庫技能 "),n("a",{class:"header-anchor",href:"#備忘單-提升你的-mariadb-和-mysql-資料庫技能","aria-label":"Permalink to “備忘單：提升你的 MariaDB 和 MySQL 資料庫技能”"},"​")],-1)),s[41]||(s[41]=n("blockquote",null,[n("p",null,"閲讀本文並下載我們的免費備忘單，去使用開源的資料庫吧。")],-1)),s[42]||(s[42]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/14/065421hq1qocmk3rf4npq1.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("當你寫一個程序或配置一個服務時，你最終都要持久化存儲信息。有時候，你只需要一個 INI 或者 ",-1)),p(e,{href:"https://www.redhat.com/sysadmin/yaml-tips"},{default:i(()=>[...s[0]||(s[0]=[a("YAML",-1)])]),_:1}),s[2]||(s[2]=a(" 配置文件就夠了。而有時候，一個自定義格式的 XML 或者 JSON 或其他類似的文件會更好。",-1))]),n("p",null,[s[5]||(s[5]=a("但也有時候你需要校驗輸入、快速查詢信息、關聯數據、通常還要熟練地處理你的用户的請求。這就是設計資料庫的目的，而 ",-1)),p(e,{href:"https://mariadb.org/"},{default:i(()=>[...s[3]||(s[3]=[a("MariaDB",-1)])]),_:1}),s[6]||(s[6]=a("（由 ",-1)),p(e,{href:"https://www.mysql.com/"},{default:i(()=>[...s[4]||(s[4]=[a("MySQL",-1)])]),_:1}),s[7]||(s[7]=a(" 的原始開發人員開發的一個分支） 是一個極佳的選項。在本文中我使用的是 MariaDB，但這些信息同樣適用於 MySQL。",-1))]),n("p",null,[s[9]||(s[9]=a("通過編程語言與資料庫進行交互是很普遍的。正因如此，出現了大量 Java、Python、Lua、PHP、Ruby、C++ 和其他語言的 ",-1)),p(e,{href:"https://en.wikipedia.org/wiki/SQL"},{default:i(()=>[...s[8]||(s[8]=[a("SQL",-1)])]),_:1}),s[10]||(s[10]=a(" 庫。然而，在使用這些庫之前，理解資料庫引擎做了什麼以及為什麼選擇資料庫是重要的對我們會很有幫助。本文介紹 MariaDB 和 ",-1)),s[11]||(s[11]=n("code",null,"mysql",-1)),s[12]||(s[12]=a(" 命令來幫助你熟悉資料庫處理數據的基本原理。",-1))]),n("p",null,[s[15]||(s[15]=a("如果你還沒有安裝 MariaDB，請查閲我的文章 ",-1)),p(e,{href:"https://opensource.com/article/20/10/install-mariadb-and-mysql-linux"},{default:i(()=>[...s[13]||(s[13]=[a("在 Linux 上安裝 MariaDB",-1)])]),_:1}),s[16]||(s[16]=a("。如果你沒有使用 Linux，請參照 MariaDB ",-1)),p(e,{href:"https://mariadb.org/download"},{default:i(()=>[...s[14]||(s[14]=[a("下載頁面",-1)])]),_:1}),s[17]||(s[17]=a("提供的指導方法。",-1))]),s[43]||(s[43]=l(`<h3 id="與-mariadb-交互" tabindex="-1">與 MariaDB 交互 <a class="header-anchor" href="#與-mariadb-交互" aria-label="Permalink to “與 MariaDB 交互”">​</a></h3><p>你可以使用 <code>mysql</code> 命令與 MariaDB 進行交互。首先使用子命令 <code>ping</code> 確認你的服務是運行着的，在提示後輸入密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u root -p ping</span></span>
<span class="line"><span>Enter password:</span></span>
<span class="line"><span>mysqld is alive</span></span></code></pre></div><p>為了易於讀者理解，打開一個交互式的 MariaDB 會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>Enter password:</span></span>
<span class="line"><span>Welcome to the MariaDB monitor.</span></span>
<span class="line"><span>Commands end with ; or \\g.</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Type &#39;help;&#39; or &#39;\\h&#39; for help.</span></span>
<span class="line"><span>Type &#39;\\c&#39; to clear the current input statement.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MariaDB [(none)]&gt;</span></span></code></pre></div><p>你現在是在一個 MariaDB 子 shell 中，提示符是 MariaDB 提示符。普通的 Bash 命令在這裏不能使用，只能用 MariaDB 命令。輸入 <code>help</code> （或 <code>?</code>）查看命令列表。這些是你的 MariaDB shell 的管理命令，使用它們可以定製你的 shell，但它們不屬於 SQL 語言。</p><h3 id="學習-sql-基本知識" tabindex="-1">學習 SQL 基本知識 <a class="header-anchor" href="#學習-sql-基本知識" aria-label="Permalink to “學習 SQL 基本知識”">​</a></h3>`,7)),n("p",null,[p(e,{href:"https://publications.opengroup.org/c449"},{default:i(()=>[...s[18]||(s[18]=[a("結構化查詢語言",-1)])]),_:1}),s[19]||(s[19]=a("是基於它們的能力定義的：一種通過有規則且一致的語法來查詢資料庫中的內容以得到有用的結果的方法。SQL 看起來像是普通的英文語句，有一點點生硬。例如，如果你登入資料庫服務器，想查看有哪些庫，輸入 ",-1)),s[20]||(s[20]=n("code",null,"SHOW DATABASES;",-1)),s[21]||(s[21]=a(" 並回車就能看到結果。",-1))]),s[44]||(s[44]=l(`<p>SQL 命令以分號作為結尾。如果你忘記輸入分號，MariaDB 會認為你是想在下一行繼續輸入你的查詢命令，在下一行你可以繼續輸入命令也可以輸入分號結束命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(NONE)]&gt; SHOW DATABASES;</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| DATABASE           |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| information_schema |</span></span>
<span class="line"><span>| mysql              |</span></span>
<span class="line"><span>| performance_schema |</span></span>
<span class="line"><span>| test               |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>4 ROWS IN SET (0.000 sec)</span></span></code></pre></div><p>上面的例子顯示當前有四個資料庫：<code>information_schema</code>、<code>mysql</code>、<code>performance_schema</code> 和 <code>test</code>。你必須指定 MariaDB 使用哪個庫，才能對該庫使用查詢語句。指定資料庫的命令是 <code>use</code>。當你選擇了一個庫後，MariaDB 提示框會切換為選擇的庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(NONE)]&gt; USE test;</span></span>
<span class="line"><span>MariaDB [(test)]&gt;</span></span></code></pre></div><h4 id="顯示資料庫的表" tabindex="-1">顯示資料庫的表 <a class="header-anchor" href="#顯示資料庫的表" aria-label="Permalink to “顯示資料庫的表”">​</a></h4><p>資料庫裏有<em>表</em>，與電子表格類似：有一系列的行（在資料庫中稱為<em>記錄</em>）和列。一個行和一個列唯一確定一個<em>字段</em>。</p><p>查看一個數據庫中可用的表（可以理解為多表單電子表格中的一頁），使用 SQL 關鍵字 <code>SHOW</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(test)]&gt; SHOW TABLES;</span></span>
<span class="line"><span>empty SET</span></span></code></pre></div><p><code>test</code> 資料庫是空的，所以使用 <code>use</code> 命令切換到 <code>mysql</code> 資料庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MariaDB [(test)]&gt; USE mysql;</span></span>
<span class="line"><span>MariaDB [(mysql)]&gt; SHOW TABLES;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>| Tables_in_mysql           |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>| column_stats              |</span></span>
<span class="line"><span>| columns_priv              |</span></span>
<span class="line"><span>| db                        |</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>| time_zone_transition_type |</span></span>
<span class="line"><span>| transaction_registry      |</span></span>
<span class="line"><span>| USER                      |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>31 ROWS IN SET (0.000 sec)</span></span></code></pre></div><p>這個資料庫中有很多表！<code>mysql</code> 資料庫是這個 MariaDB 實例的系統管理資料庫。它裏面包含重要數據，比如用來管理資料庫權限的用户結構。這個資料庫很重要，你不需要經常直接與它交互，但是使用 SQL 腳本來操作它卻很常見。當你學習 MariaDB 時理解 <code>mysql</code> 資料庫很有用，因為它有助於説明一些基本的 SQL 命令。</p><h4 id="檢查一個表" tabindex="-1">檢查一個表 <a class="header-anchor" href="#檢查一個表" aria-label="Permalink to “檢查一個表”">​</a></h4><p>這個實例的 <code>mysql</code> 資料庫的最後一個表名為 <code>USER</code>。這個表包含了可以訪問這個資料庫的用户。當前裏面只有一個 root 用户，但是你可以添加不同權限的用户，賦予它們查看、更新或創建數據的權限。你可以查看一個表的列首來了解一個 MariaDB 用户的所有屬性：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SHOW COLUMNS IN USER;</span></span>
<span class="line"><span>MariaDB [mysql]&gt; SHOW COLUMNS IN USER;</span></span>
<span class="line"><span>+-------------+---------------+------+-----+----------+</span></span>
<span class="line"><span>| FIELD       | TYPE          | NULL | KEY | DEFAULT  |</span></span>
<span class="line"><span>+-------------+---------------+------+-----+----------+</span></span>
<span class="line"><span>| Host        | CHAR(60)      | NO   | PRI |          |</span></span>
<span class="line"><span>| USER        | CHAR(80)      | NO   | PRI |          |</span></span>
<span class="line"><span>| Password    | CHAR(41)      | NO   |     |          |</span></span>
<span class="line"><span>| Select_priv | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>| Insert_priv | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>| Update_priv | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>| Delete_priv | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>| Create_priv | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>| Drop_priv   | enum(&#39;N&#39;,&#39;Y&#39;) | NO   |     | N        |</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>47 ROWS IN SET (0.001 sec)</span></span></code></pre></div><h4 id="創建一個新的用户" tabindex="-1">創建一個新的用户 <a class="header-anchor" href="#創建一個新的用户" aria-label="Permalink to “創建一個新的用户”">​</a></h4><p>不論你是否需要一個普通的賬號來管理資料庫或者為計算機配置資料庫（例如安裝 WordPress、Drupal 或 Joomla時），在 MariaDB 中多建一個用户賬號是很普遍的。你可以通過向 <code>mysql</code> 資料庫的 <code>USER</code> 表中添加一個用户或使用 SQL 關鍵字 <code>CREATE</code> 來提示 MariaDB 創建一個 MariaDB 用户。使用 <code>CREATE</code> 來創建新用户會默認執行一些有用的方法，因此你不需要手動生成所有的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE USER &#39;tux&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;really_secure_password&#39;;</span></span></code></pre></div><h4 id="查看錶的字段" tabindex="-1">查看錶的字段 <a class="header-anchor" href="#查看錶的字段" aria-label="Permalink to “查看錶的字段”">​</a></h4><p>你可以使用 <code>SELECT</code> 關鍵字來查看資料庫表的字段和值。這本例中，你創建了一個名為 <code>tux</code> 的用户，因此查詢 <code>USER</code> 表中的列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT USER,host FROM USER;</span></span>
<span class="line"><span>+------+------------+</span></span>
<span class="line"><span>| USER | host       |</span></span>
<span class="line"><span>+------+------------+</span></span>
<span class="line"><span>| root | localhost  |</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>| tux  | localhost  |</span></span>
<span class="line"><span>+------+------------+</span></span>
<span class="line"><span>7 ROWS IN SET (0.000 sec)</span></span></code></pre></div><h4 id="為一個用户賦予權限" tabindex="-1">為一個用户賦予權限 <a class="header-anchor" href="#為一個用户賦予權限" aria-label="Permalink to “為一個用户賦予權限”">​</a></h4><p>通過查看 <code>USER</code> 表列出的信息，你可以看到用户的狀態。例如，新用户 <code>tux</code> 對這個資料庫沒有任何權限。使用 <code>WHERE</code> 語句你可以只查 <code>tux</code> 那一條記錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT USER,select_priv,insert_priv,update_priv FROM USER WHERE USER=&#39;tux&#39;;</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span>
<span class="line"><span>| USER | select_priv | insert_priv | update_priv |</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span>
<span class="line"><span>| tux  | N           | N           | N           |</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span></code></pre></div><p>使用 <code>GRANT</code> 命令修改用户的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; GRANT SELECT ON *.* TO &#39;tux&#39;@&#39;localhost&#39;;</span></span>
<span class="line"><span>&gt; FLUSH PRIVILEGES;</span></span></code></pre></div><p>驗證你的修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT USER,select_priv,insert_priv,update_priv FROM USER WHERE USER=&#39;tux&#39;;</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span>
<span class="line"><span>| USER | select_priv | insert_priv | update_priv |</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span>
<span class="line"><span>| tux  | Y           | N           | N           |</span></span>
<span class="line"><span>+------+-------------+-------------+-------------+</span></span></code></pre></div><p><code>tux</code> 用户現在有了從所有表中查詢記錄的權限。</p><h3 id="創建自定義的資料庫" tabindex="-1">創建自定義的資料庫 <a class="header-anchor" href="#創建自定義的資料庫" aria-label="Permalink to “創建自定義的資料庫”">​</a></h3><p>到目前為止，你一直在與默認的資料庫進行交互。除了用户管理，大部分人很少會與默認的資料庫進行交互。通常，你會用自定義的數據來填充創建的資料庫。</p><h4 id="創建一個-mariadb-資料庫" tabindex="-1">創建一個 MariaDB 資料庫 <a class="header-anchor" href="#創建一個-mariadb-資料庫" aria-label="Permalink to “創建一個 MariaDB 資料庫”">​</a></h4><p>你可能已經可以自己在 MariaDB 中創建新資料庫了。創建資料庫跟新建用户差不多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE DATABASE example;</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.000 sec)</span></span>
<span class="line"><span>&gt; SHOW DATABASES;</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| DATABASE           |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| example            |</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>使用 <code>use</code> 命令來把這個新建的資料庫作為當前使用的庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; USE example;</span></span></code></pre></div><h4 id="創建一個表" tabindex="-1">創建一個表 <a class="header-anchor" href="#創建一個表" aria-label="Permalink to “創建一個表”">​</a></h4><p>創建表比創建資料庫要複雜，因為你必須定義列首。MariaDB 提供了很多方便的函數，可以用於創建列，引入數據類型定義，自增選項，對空值的約束，自動時間戳等等。</p><p>下面是用來描述一系列用户的一個簡單的表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE TABLE IF NOT EXISTS member (</span></span>
<span class="line"><span>    -&gt; id INT AUTO_INCREMENT PRIMARY KEY,</span></span>
<span class="line"><span>    -&gt; name VARCHAR(128) NOT NULL,</span></span>
<span class="line"><span>    -&gt; startdate TIMESTAMP DEFAULT CURRENT_TIMESTAMP);</span></span>
<span class="line"><span>Query OK, 0 ROWS affected (0.030 sec)</span></span></code></pre></div><p>這個表通過使用一個自動遞增的方法來唯一標識每一行。表示用户名字的字段不能為空（或 <code>null</code>），每一行被創建時會自動生成時間戳。</p><p>使用 SQL 關鍵字 <code>INSERT</code> 向這個表填充一些示例數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; INSERT INTO member (name) VALUES (&#39;Alice&#39;);</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.011 sec)</span></span>
<span class="line"><span>&gt; INSERT INTO member (name) VALUES (&#39;Bob&#39;);</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.011 sec)</span></span>
<span class="line"><span>&gt; INSERT INTO member (name) VALUES (&#39;Carol&#39;);</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.011 sec)</span></span>
<span class="line"><span>&gt; INSERT INTO member (name) VALUES (&#39;David&#39;);</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.011 sec)</span></span></code></pre></div><p>驗證一下表裏的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT * FROM member;</span></span>
<span class="line"><span>+----+-------+---------------------+</span></span>
<span class="line"><span>| id | name  | startdate           |</span></span>
<span class="line"><span>+----+-------+---------------------+</span></span>
<span class="line"><span>|  1 | Alice | 2020-10-03 15:25:06 |</span></span>
<span class="line"><span>|  2 | Bob   | 2020-10-03 15:26:43 |</span></span>
<span class="line"><span>|  3 | Carol | 2020-10-03 15:26:46 |</span></span>
<span class="line"><span>|  4 | David | 2020-10-03 15:26:51 |</span></span>
<span class="line"><span>+----+-------+---------------------+</span></span>
<span class="line"><span>4 ROWS IN SET (0.000 sec)</span></span></code></pre></div><h4 id="同時增加多行數據" tabindex="-1">同時增加多行數據 <a class="header-anchor" href="#同時增加多行數據" aria-label="Permalink to “同時增加多行數據”">​</a></h4><p>再創建一個表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE TABLE IF NOT EXISTS linux (</span></span>
<span class="line"><span>    -&gt; id INT AUTO_INCREMENT PRIMARY KEY,</span></span>
<span class="line"><span>    -&gt; distro VARCHAR(128) NOT NULL);</span></span>
<span class="line"><span>Query OK, 0 ROWS affected (0.030 sec)</span></span></code></pre></div><p>填充一些示例數據，這次使用 <code>VALUES</code> 快捷方式，這樣你可以一次添加多行數據。<code>VALUES</code> 關鍵字需要一個用括號包圍的列表作為參數，也可以用逗號分隔的多個列表作為參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; INSERT INTO linux (distro)</span></span>
<span class="line"><span> -&gt; VALUES (&#39;Slackware&#39;), (&#39;RHEL&#39;),(&#39;Fedora&#39;),(&#39;Debian&#39;);</span></span>
<span class="line"><span>Query OK, 4 ROWS affected (0.011 sec)</span></span>
<span class="line"><span>Records: 4  Duplicates: 0  Warnings: 0</span></span>
<span class="line"><span>&gt; SELECT * FROM linux;</span></span>
<span class="line"><span>+----+-----------+</span></span>
<span class="line"><span>| id | distro    |</span></span>
<span class="line"><span>+----+-----------+</span></span>
<span class="line"><span>|  1 | Slackware |</span></span>
<span class="line"><span>|  2 | RHEL      |</span></span>
<span class="line"><span>|  3 | Fedora    |</span></span>
<span class="line"><span>|  4 | Debian    |</span></span>
<span class="line"><span>+----+-----------+</span></span></code></pre></div><h3 id="關聯多個表" tabindex="-1">關聯多個表 <a class="header-anchor" href="#關聯多個表" aria-label="Permalink to “關聯多個表”">​</a></h3><p>現在你有兩個表，之間沒有關聯。兩個表的數據是獨立的，但是你可能需要表一中的一個值來識別表二的記錄。</p><p>你可以在表一中新增一列對應表二中的值。因為兩個表都有唯一的標識符（自動遞增的 <code>id</code> 字段），關聯的它們的最簡單的方式是，使用表一中的 <code>id</code> 字段作為表二的查詢條件。</p><p>在表一中創建一列用來表示表二中的一個值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; ALTER TABLE member ADD COLUMN (os INT);</span></span>
<span class="line"><span>Query OK, 0 ROWS affected (0.012 sec)</span></span>
<span class="line"><span>Records: 0  Duplicates: 0  Warnings: 0</span></span>
<span class="line"><span>&gt; DESCRIBE member;</span></span>
<span class="line"><span>DESCRIBE member;</span></span>
<span class="line"><span>+-----------+--------------+------+-----+---------+------+</span></span>
<span class="line"><span>| FIELD     | TYPE         | NULL | KEY | DEFAULT | Extra|</span></span>
<span class="line"><span>+-----------+--------------+------+-----+---------+------+</span></span>
<span class="line"><span>| id        | INT(11)      | NO   | PRI | NULL    | auto_|</span></span>
<span class="line"><span>| name      | VARCHAR(128) | NO   |     | NULL    |      |</span></span>
<span class="line"><span>| startdate | TIMESTAMP    | NO   |     | cur[...]|      |</span></span>
<span class="line"><span>| os        | INT(11)      | YES  |     | NULL    |      |</span></span>
<span class="line"><span>+-----------+--------------+------+-----+---------+------+</span></span></code></pre></div><p>把 <code>linux</code> 表中的唯一 ID 分配給每個成員。因為記錄已經存在，使用 <code>UPDATE</code> 關鍵字而不是 <code>INSERT</code>。尤其是當你想查詢某行然後再更新某列值時。語法上，表達方式有點倒裝，先更新後查詢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; UPDATE member SET os=1 WHERE name=&#39;Alice&#39;;</span></span>
<span class="line"><span>Query OK, 1 ROW affected (0.007 sec)</span></span>
<span class="line"><span>ROWS matched: 1  Changed: 1  Warnings: 0</span></span></code></pre></div><p>要填充數據，請對其他名字重複執行這個過程。為了數據的多樣性，在四行記錄中分配三個不同的值。</p><h4 id="連接表" tabindex="-1">連接表 <a class="header-anchor" href="#連接表" aria-label="Permalink to “連接表”">​</a></h4><p>現在這兩個表彼此有了關聯，你可以使用 SQL 來展示關聯的數據。資料庫中有很多種連接方式，你可以盡請嘗試。下面的例子是關聯 <code>member</code> 表中 <code>os</code> 字段和 <code>linux</code> 表中 <code>id</code> 字段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT * FROM member JOIN linux ON member.os=linux.id;</span></span>
<span class="line"><span>+----+-------+---------------------+------+----+-----------+</span></span>
<span class="line"><span>| id | name  | startdate           | os   | id | distro    |</span></span>
<span class="line"><span>+----+-------+---------------------+------+----+-----------+</span></span>
<span class="line"><span>|  1 | Alice | 2020-10-03 15:25:06 |    1 |  1 | Slackware |</span></span>
<span class="line"><span>|  2 | Bob   | 2020-10-03 15:26:43 |    3 |  3 | Fedora    |</span></span>
<span class="line"><span>|  4 | David | 2020-10-03 15:26:51 |    3 |  3 | Fedora    |</span></span>
<span class="line"><span>|  3 | Carol | 2020-10-03 15:26:46 |    4 |  4 | Debian    |</span></span>
<span class="line"><span>+----+-------+---------------------+------+----+-----------+</span></span>
<span class="line"><span>4 ROWS IN SET (0.000 sec)</span></span></code></pre></div><p>連接 <code>os</code> 和 <code>id</code> 字段。</p><p>在圖形化的應用中，你可以想像 <code>os</code> 字段可以在下拉菜單中設置，值的來源是 <code>linux</code> 表中的 <code>distro</code> 字段。通過使用多個表中獨立卻有關聯的數據，你可以保證數據的一致性和有效性，使用 SQL 你可以動態地關聯它們。</p><h3 id="下載-mariadb-和-mysql-備忘單" tabindex="-1">下載 MariaDB 和 MySQL 備忘單 <a class="header-anchor" href="#下載-mariadb-和-mysql-備忘單" aria-label="Permalink to “下載 MariaDB 和 MySQL 備忘單”">​</a></h3>`,63)),n("p",null,[s[23]||(s[23]=a("MariaDB 是企業級的資料庫。它是健壯、強大、高效的資料庫引擎。學習它是你向管理 web 應用和編寫語言庫邁出的偉大的一步。你可以",-1)),p(e,{href:"https://opensource.com/downloads/mariadb-mysql-cheat-sheet"},{default:i(()=>[...s[22]||(s[22]=[a("下載 MariaDB 和 MySQL 備忘單",-1)])]),_:1}),s[24]||(s[24]=a("，在你使用 MariaDB 時可以快速參考。",-1))]),s[45]||(s[45]=n("hr",null,null,-1)),n("p",null,[s[26]||(s[26]=a("via: ",-1)),p(e,{href:"https://opensource.com/article/20/10/mariadb-mysql-cheat-sheet"},{default:i(()=>[...s[25]||(s[25]=[a("https://opensource.com/article/20/10/mariadb-mysql-cheat-sheet",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("作者：",-1)),p(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[27]||(s[27]=[a("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=a(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[28]||(s[28]=[a("lujun9972",-1)])]),_:1}),s[33]||(s[33]=a(" 譯者：",-1)),p(e,{href:"https://github.com/lxbwolf"},{default:i(()=>[...s[29]||(s[29]=[a("lxbwolf",-1)])]),_:1}),s[34]||(s[34]=a(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[37]||(s[37]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[36]||(s[36]=[a("Linux中國",-1)])]),_:1}),s[39]||(s[39]=a(" 榮譽推出",-1))])])}const y=t(c,[["render",h]]);export{E as __pageData,y as default};
